-- MOSTARDA — Seed Data for Testing

CREATE OR REPLACE FUNCTION seed.generate_slots(p_tv_id uuid, p_start_date date, p_num_days integer DEFAULT 7, p_start_hour integer DEFAULT 8, p_end_hour integer DEFAULT 22) RETURNS integer LANGUAGE plpgsql AS $$ DECLARE v_date date; v_seq integer; v_hour integer; v_created integer := 0; BEGIN FOR day_offset IN 0..(p_num_days - 1) LOOP v_date := p_start_date + day_offset; v_seq := 0; FOR v_hour IN p_start_hour..(p_end_hour - 1) LOOP INSERT INTO public.tv_slots (tv_id, date, start_time, end_time, duration, sequence_number, status, base_price, current_price, estimated_audience, created_at, updated_at) VALUES (p_tv_id, v_date, make_time(v_hour, 0, 0), make_time(v_hour, 30, 0), 30, v_seq, 'available', 100, 100, 30 + floor(random() * 70)::integer, now_utc(), now_utc()); v_seq := v_seq + 1; v_created := v_created + 1; INSERT INTO public.tv_slots (tv_id, date, start_time, end_time, duration, sequence_number, status, base_price, current_price, estimated_audience, created_at, updated_at) VALUES (p_tv_id, v_date, make_time(v_hour, 30, 0), make_time(v_hour + 1, 0, 0), 30, v_seq, 'available', 100, 100, 30 + floor(random() * 70)::integer, now_utc(), now_utc()); v_seq := v_seq + 1; v_created := v_created + 1; END LOOP; END LOOP; RETURN v_created; END $$;

ON CONFLICT (email) DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT (slug) DO NOTHING;

ON CONFLICT (identifier) DO NOTHING;

SELECT seed.generate_slots(id, CURRENT_DATE, 7) FROM public.tvs;

DO $$ DECLARE v_campaign_id uuid; v_slot_ids uuid[]; v_price bigint; v_cs_id uuid; BEGIN INSERT INTO public.campaigns (advertiser_id, name, brand_name, budget, status, start_date, end_date, preferred_categories, preferred_cities, preferred_states, day_parts, auto_optimize, affiliate_seller_id, created_at, updated_at) VALUES ('11111111-1111-4111-8111-111111111111', 'Lançamento TechBrasil Verão 2027', 'TechBrasil', 1000000, 'active', CURRENT_DATE, CURRENT_DATE + 30, ARRAY['mall','bus_station','gym'], ARRAY['São Paulo','Rio de Janeiro'], ARRAY['SP','RJ'], ARRAY['morning','afternoon','evening'], true, '44444444-4444-4444-8444-444444444444', now_utc(), now_utc()) RETURNING id INTO v_campaign_id; SELECT ARRAY_AGG(id ORDER BY start_time) INTO v_slot_ids FROM public.tv_slots WHERE tv_id = 'b1000000-0000-4000-8000-000000000001' AND date = CURRENT_DATE + 1 AND start_time BETWEEN '08:00' AND '11:00' LIMIT 3; IF array_length(v_slot_ids, 1) >= 3 THEN v_price := 20000; INSERT INTO public.campaign_slots (campaign_id, slot_id, tv_id, price_paid, is_confirmed, booked_at) VALUES (v_campaign_id, v_slot_ids[1], 'b1000000-0000-4000-8000-000000000001', v_price, true, now_utc()) RETURNING id INTO v_cs_id; UPDATE public.tv_slots SET status = 'booked', campaign_id = v_campaign_id, campaign_slot_id = v_cs_id, current_price = v_price, updated_at = now_utc() WHERE id = v_slot_ids[1]; v_price := 22000; INSERT INTO public.campaign_slots (campaign_id, slot_id, tv_id, price_paid, is_confirmed, booked_at) VALUES (v_campaign_id, v_slot_ids[2], 'b1000000-0000-4000-8000-000000000001', v_price, true, now_utc()) RETURNING id INTO v_cs_id; UPDATE public.tv_slots SET status = 'booked', campaign_id = v_campaign_id, campaign_slot_id = v_cs_id, current_price = v_price, updated_at = now_utc() WHERE id = v_slot_ids[2]; v_price := 25000; INSERT INTO public.campaign_slots (campaign_id, slot_id, tv_id, price_paid, is_confirmed, booked_at) VALUES (v_campaign_id, v_slot_ids[3], 'b1000000-0000-4000-8000-000000000001', v_price, true, now_utc()) RETURNING id INTO v_cs_id; UPDATE public.tv_slots SET status = 'booked', campaign_id = v_campaign_id, campaign_slot_id = v_cs_id, current_price = v_price, updated_at = now_utc() WHERE id = v_slot_ids[3]; END IF; END $$;

DO $$ DECLARE v_election_id uuid; BEGIN INSERT INTO public.elections (tv_id, status, start_date, end_date, candidates, total_votes, total_weighted_votes, created_at, updated_at) VALUES ('b1000000-0000-4000-8000-000000000001', 'active', CURRENT_DATE - 15, CURRENT_DATE + 15, jsonb_build_array(jsonb_build_object('user_id','55555555-5555-4555-8555-555555555555','name','Lucia Pereira','vote_count',5,'weighted_vote_count',12.5,'is_incumbent',true,'nominated_at',now_utc()), jsonb_build_object('user_id','22222222-2222-4222-8222-222222222222','name','Carlos Oliveira','vote_count',3,'weighted_vote_count',7.5,'is_incumbent',false,'nominated_at',now_utc())), 8, 20.0, now_utc(), now_utc()) RETURNING id INTO v_election_id; INSERT INTO public.votes (election_id, tv_id, voter_id, voter_type, candidate_id, weight, is_verified, voted_at) VALUES (v_election_id, 'b1000000-0000-4000-8000-000000000001', '33333333-3333-4333-8333-333333333333', 'space_owner', '55555555-5555-4555-8555-555555555555', 3.0, true, now_utc() - interval '5 days'), (v_election_id, 'b1000000-0000-4000-8000-000000000001', '44444444-4444-4444-8444-444444444444', 'affiliate_seller', '55555555-5555-4555-8555-555555555555', 2.0, true, now_utc() - interval '4 days'), (v_election_id, 'b1000000-0000-4000-8000-000000000001', '22222222-2222-4222-8222-222222222222', 'tv_owner', '22222222-2222-4222-8222-222222222222', 2.5, true, now_utc() - interval '3 days'), (v_election_id, 'b1000000-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111111', 'advertiser', '55555555-5555-4555-8555-555555555555', 1.0, true, now_utc() - interval '2 days') ON CONFLICT (election_id, voter_id) DO NOTHING; END $$;




DROP FUNCTION IF EXISTS seed.generate_slots;
